/**
 * A minimal TrueType font with a single rectangle-outline .notdef glyph and
 * no cmap entries: every code point falls back to the box glyph. This mirrors
 * upstream WeasyPrint's documented no-fonts behavior ("all letters turn into
 * rectangles") — the port renders this font when no other fonts are available
 * instead of crashing.
 */
const BASE64 =
  '';

export const NOTDEF_TTF_BASE64 = BASE64;
